// This method refreshes grid on user click "Refresh" button.
if (window.wasRefreshImpactGridForceServerCallMethodCalledBefore)
{
	const expressEcoImpactMatrixRelationshipTypeId = "1A6269964DD94DEA98E530E391EF3395";

	const topWnd = aras.getMostTopWindowWithAras(window);

	const expressEcoImpactMatrixRelationshipIframe = topWnd.relationshipsControl.iframesCollection[expressEcoImpactMatrixRelationshipTypeId];

	if (expressEcoImpactMatrixRelationshipIframe) {
		const formFrame = expressEcoImpactMatrixRelationshipIframe.contentWindow.document.getElementById('formFrame');
		const impactGrid = formFrame && formFrame.contentWindow && formFrame.contentWindow.impactGrid;

		if (impactGrid && impactGrid.ready && impactGrid.refreshGridWithTimout) {
			formFrame.contentWindow.impactGrid.refreshGridWithTimout(true);
		}
	}
} else {
	window.wasRefreshImpactGridForceServerCallMethodCalledBefore = true;
}
